class Solution {
public:
    long long minimumFuelCost(vector<vector<int>>& roads, int seats) {
        int n = roads.size() + 1;
        vector<vector<int>> adj(n);
        for (auto& r : roads) {
            adj[r[0]].push_back(r[1]);
            adj[r[1]].push_back(r[0]);
        }
        long long ans = 0;
        vector<int> parent(n, -1);
        vector<long long> sz(n, 1);
        vector<int> order;
        order.reserve(n);
        vector<int> q;
        q.reserve(n);
        q.push_back(0);
        vector<char> visited(n, 0);
        visited[0] = 1;
        for (int i = 0; i < (int)q.size(); i++) {
            int u = q[i];
            order.push_back(u);
            for (int v : adj[u]) {
                if (!visited[v]) {
                    visited[v] = 1;
                    parent[v] = u;
                    q.push_back(v);
                }
            }
        }
        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            if (parent[u] != -1) {
                ans += (sz[u] + seats - 1) / seats;
                sz[parent[u]] += sz[u];
            }
        }
        return ans;
    }
};
